CohStatus coh_salvage_tab(const CohSalvageDictionary*d,CohBytes name,uint32_t*out){CohStatus s=query(d,name,out);if(s!=COH_OK)return s;for(unsigned i=0;i<d->tab_count;i++){int m=match(d,d->tabs[i].name,name);if(m<0)return COH_STATE;if(m){*out=i;return COH_OK;}}return COH_NOT_FOUND;}
CohStatus coh_salvage_workshop(const CohSalvageDictionary*d,uint32_t row,uint32_t index,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;if(row>=d->count)return COH_NOT_FOUND;CohSalvageRange a=d->items[row].arrays[0];if(a.first>d->value_count||a.count>d->value_count-a.first)return COH_STATE;if(index>=a.count)return COH_NOT_FOUND;uint32_t n=d->values[a.first+index].detail_plus_one;if(!n||n>d->details_count)return COH_STATE;*out=n-1;return COH_OK;}
